xe0\xed\xe8\xff \xf1\xf2\xee\xeb\xe1\xf6\xee\xe2*/\n      for ($i=0;$i<@mysql_num_fields($result_tbl);$i++){\n           $name_tbl=mysql_field_name($result_tbl,$i);\n           print "<td bgcolor=#C7C5C5>$name_tbl</td>";   \n      } \n\n      print "</tr>";\n      while ($line_tbl = @mysql_fetch_array($result_tbl, MYSQL_ASSOC)) {\n         print "<tr>";\n         foreach ($line_tbl as $key_tbl =>$col_value_tbl) {          \n             print "<td bgcolor=#EDEEF1>".htmlspecialchars($col_value_tbl)."</td>";\n         }\n         print "</tr>";\n      }\n      print "</table><br>";\n      @mysql_free_result($result_tbl);\n   }\n}\n\n/*-------------\xef\xee\xea\xe0\xe7\xe0\xf2\xfc \xf1\xf2\xf0\xee\xea\xe8 \xf2\xe0\xe1\xeb\xe8\xf6\xfb--------------*/\nif (!isset($alter_table) && !isset($st_tab) && !isset($query_tbl) && !isset($new_query_tbl) && \n!isset($dump) && !isset($strukt) && !isset($query_edit) && !isset($query_del) && !isset($q_get) && \n!isset($nn_row) && !isset($nn) && !isset($upd_f)) {\n  print "<br><table border=0 cellpadding=1 cellspacing=1 width=100% bgcolor=#FFFFFF><tr>";\n\n//\xee\xef\xf0\xe5\xe4\xe5\xeb\xff\xe5\xec \xe8\xed\xe4\xe5\xea\xf1 \xe4\xeb\xff \xf2\xe0\xe1\xeb\xe8\xf6\xfb, \xef\xee \xea\xe0\xea\xee\xec\xf3 \xef\xee\xeb\xfe(\xef\xee\xeb\xff\xec) \xe1\xf3\xe4\xe5\xec \xe8\xf1\xea\xe0\xf2\xfc \xf0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xf3\xe5\xec\xf3\xfe \xe7\xe0\xef\xe8\xf1\xfc\n//Key_name \xc8\xec\xff \xe8\xed\xe4\xe5\xea\xf1\xe0, Column_name \xc8\xec\xff \xf1\xf2\xee\xeb\xe1\xf6\xe0\n$query_ind = "SHOW KEYS FROM `{$tbl}`";\n$result_ind = mysql_query($query_ind) or die("$h_error<b>".mysql_error()."</b>$f_error");\n\nwhile ($row = mysql_fetch_array($result_ind, MYSQL_ASSOC)) {\n    if ($row[\'Key_name\'] == \'PRIMARY\') {\n        $primary[] .= $row[\'Column_name\'];\n    } \n}\n \nmysql_free_result($result_ind);\n\n $query = "SELECT * FROM `{$tbl}` LIMIT {$limit_start},{$limit_count}";\n $result = mysql_query($query) or die("$h_error<b>".mysql_error()."</b>$f_error");\nif (mysql_num_rows($result) == 0) {\n  print "\xd2\xe0\xe1\xeb\xe8\xf6\xe0 <b>$tbl</b> \xed\xe5 \xf1\xee\xe4\xe5\xf0\xe6\xe8\xf2 \xed\xe8 \xee\xe4\xed\xee\xe9 \xe7\xe0\xef\xe8\xf1\xe8";\n}else{\n  /*\xef\xee\xeb\xf3\xf7\xe0\xe5\xec \xed\xe0\xe7\xe2\xe0\xed\xe8\xff \xf1\xf2\xee\xeb\xe1\xf6\xee\xe2*/\n  print "<td bgcolor=#E6E7E9></td><td bgcolor=#E6E7E9></td>";\n  for ($i=0;$i<mysql_num_fields($result);$i++){\n    $name=mysql_field_name($result,$i);\n    print "<td bgcolor=#C7C5C5>$name</td>";   \n  } \n}\n  while ($line = mysql_fetch_array($result, MYSQL_ASSOC)) {\n     print "</tr>";\n\n     foreach ($line as $key =>$col_value) {\n\n         if (count($primary) > 0) { \n           if (in_array($key,$primary)) { $edit .= urlencode("`$key`=\'$col_value\' AND "); } \n         } \n         else {\n            //if (strlen($col_value) >= 20) { \n            //   $e_count=substr($col_value,0,20);\n            //   $edit .= urlencode("`$key`=\'$e_count\' AND ");\n            //} else {\n               $edit .= urlencode("`$key`=\'$col_value\' AND ");\n            //}\n            \n         } \n\n        $string .= "<td bgcolor=#EDEEF1>".htmlspecialchars($col_value)."</td>";\n     }\n       $edit=substr_replace($edit,"",-5); //\xee\xf2\xe1\xf0\xee\xf1\xe8\xf2\xfc \xef\xee\xf1\xeb\xe5\xe4\xed\xe8\xe9 +AND+\n       print "<tr><td bgcolor=#97C8D4 width=25><a href=$self?query_edit=$edit&s=y&login=$login&passwd=$passwd&server=$server&port=$port&db=$db&tbl=$tbl title=\\"\xd0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xf2\xfc \xe7\xed\xe0\xf7\xe5\xed\xe8\xff \xea\xee\xeb\xee\xed\xee\xea\\">Edit</a></td>".\n             "<td bgcolor=#F84C6C width=25><a href=\\"$self?query_del=$edit&s=y&login=$login&passwd=$passwd&server=$server&port=$port&db=$db&tbl=$tbl\\" title=\\"\xd3\xe4\xe0\xeb\xe8\xf2\xfc \xe7\xe0\xef\xe8\xf1\xfc\\" onClick=\\"return confirm(\'\xd3\xe4\xe0\xeb\xe8\xf2\xfc \xe7\xe0\xef\xe8\xf1\xfc, \xf3\xe2\xe5\xf0\xe5\xed\xfb ?\');\\">Del</a></td>".\n             $string."";\n    \n       unset($edit);\n       unset($string);\n  }\n\n  mysql_free_result($result);\n  print "</table><br>";\n}\n\n//\xf3\xe4\xe0\xeb\xff\xe5\xec \xe7\xe0\xef\xe8\xf1\xfc\nif (isset($query_del)) {\n $query = \'DELETE FROM `\'.$tbl.\'` WHERE \'.urldecode($query_del);\n $r_del = mysql_query($query) or die("$h_error<b>".mysql_error()."</b>$f_error");\n print "\xd3\xf1\xef\xe5\xf8\xed\xee \xf3\xe4\xe0\xeb\xe5\xed\xee \xf1\xf2\xf0\xee\xea (<b> ".mysql_affected_rows()."</b> )";\n\n}\n\n//\xe2\xfb\xe2\xee\xe4\xe8\xec \xf4\xee\xf0\xec\xf3 \xf0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xed\xe8\xff \xf1\xf2\xf0\xee\xea\xe8\nif (isset($query_edit)) {\n $query = \'SELECT * FROM `\'.$tbl.\'` WHERE \'.urldecode($query_edit);\n $r_edit = mysql_query($query) or die("$h_error<b>".mysql_error()."</b>$f_error"); \n\n\nprint "<br><center><font color=green><h5>\xd0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xed\xe8\xe5 \xe7\xed\xe0\xf7\xe5\xed\xe8\xe9 \xef\xee\xeb\xe5\xe9 \xf2\xe0\xe1\xeb\xe8\xf6\xfb</h5></font></center>".\n      "<table border=0 cellpadding=1 cellspacing=1 bgcolor=#FFFFFF><tr bgcolor=#C7C5C5>".\n      "<td align=center><b>\xcf\xee\xeb\xe5</b></td><td align=center><b>\xc7\xed\xe0\xf7\xe5\xed\xe8\xe5</b></td></tr>";\nprint   "<form method=\\"get\\" action=\\"$self\\">".\n        "<input type=\\"hidden\\" name=\\"s\\" value=\\"$s\\">".\n        "<input type=\\"hidden\\" name=\\"q_get\\" value=\\"y\\">".\n        "<input type=\\"hidden\\" name=\\"server\\" value=\\"$server\\">".\n        "<input type=\\"hidden\\" name=\\"port\\" value=\\"$port\\">".\n        "<input type=\\"hidden\\" name=\\"login\\" value=\\"$login\\">".\n        "<input type=\\"hidden\\" name=\\"passwd\\" value=\\"$passwd\\">".\n        "<input type=\\"hidden\\" name=\\"db\\" value=\\"$db\\">".\n        "<input type=\\"hidden\\" name=\\"tbl\\" value=\\"$tbl\\">";\n     print "<input type=\\"radio\\" name=\\"up_str\\" value=\\"up_ok\\" checked=\\"checked\\">\xce\xe1\xed\xee\xe2\xe8\xf2\xfc \xe7\xed\xe0\xf7\xe5\xed\xe8\xff&nbsp;&nbsp;<b>\xc8\xcb\xc8</b>&nbsp;&nbsp;&nbsp;".\n           "<input type=\\"radio\\" name=\\"up_str\\" value=\\"ins_ok\\">\xc2\xf1\xf2\xe0\xe2\xe8\xf2\xfc \xed\xee\xe2\xfb\xe9 \xf0\xff\xe4<br><br>";\n\n  while ($line = mysql_fetch_array($r_edit, MYSQL_ASSOC)) {\n     foreach ($line as $key =>$col_value) {\n        $del_str_\xf1 .= "`$key`=\'$col_value\' AND ";\n        $len_value=strlen($col_value);\n        if ($len_value > 40) { $t_value="<textarea name=$key cols=39 rows=5>$col_value</textarea>"; }\n        else { $t_value="<input type=\'text\' name=\'$key\' value=\'$col_value\'size=40>"; }\n        $g_query .= "<tr><td bgcolor=#DBDCDD><b>$key</b></td><td>$t_value</td></tr>";\n     }\n  }\n     $del_str=urlencode($del_str_\xf1);\n     print "<input type=\\"hidden\\" name=\\"del_str\\" value=\\"$del_str\\">";\n     print "$g_query</table><br>";\n     print "<br><input type=submit value=\\"\xe8\xe7\xec\xe5\xed\xe8\xf2\xfc \xe7\xed\xe0\xf7\xe5\xed\xe8\xe5\\"></form>";\n}\n\nif (isset($q_get)) {\n  $url=$_SERVER[\'QUERY_STRING\'];\n  if ($_GET[\'up_str\']==\'up_ok\') {\n     $del_str=urldecode(substr_replace($del_str,"",-5));\n     $b = explode(\'&\', $url);\n     for ($i = 10; $i < count($b); $i++) {\n        $q = explode("=",$b[$i]);\n        $q_a .= "`".$q[0]."`=\'".$q[1]."\', ";\n     }\n     $q_a_ins=urldecode(substr_replace($q_a,"",-2));\n     $q_st=urldecode(substr_replace($q_st,"",-2));\n     //\xf7\xf2\xee \xe7\xe0\xec\xe5\xed\xff\xe5\xec $del_str \n     //\xed\xe0 \xf7\xf2\xee \xe1\xf3\xe4\xe5\xec \xec\xe5\xed\xff\xf2\xfc $q_a_ins\n\n     $up="UPDATE `$tbl` SET $q_a_ins WHERE $del_str LIMIT 1";\n     $q_ins_new = mysql_query($up) or die("$h_error<b>".mysql_error()."</b>$f_error");\n     $c_a_r=mysql_affected_rows();\n     print "<table align=left width=70% bgcolor=#D7D8DA><tr><td><font color=green>".\n           "<b>PHP-\xea\xee\xe4 \xe7\xe0\xef\xf0\xee\xf1\xe0:</b></font></td></tr><tr><td>\\$sql=\\"$up\\";</td>".\n       